+            ListTasksResponse tasks2 = client().admin()
+                .cluster()
+                .listTasks(new ListTasksRequest().setActions("geoip-downloader[c]"))
+                .actionGet();
+            assertEquals(0, tasks2.getTasks().size());
+        });
+    }
